-- Reviewed senior batch 022; all images remotely verified.
begin;
do $guard$ declare batch_content jsonb := $senior_content$[{"source_id":4731,"word":"lavish","meaning":"奢華的","example":"The lavish banquet used far more food than the guests could eat.","example_zh":"奢華宴席準備遠超賓客能吃完的食物。","original_meaning":"奢華的","original_example":"A lavish party.","original_example_zh":"一場盛大的派對。"},{"source_id":4732,"word":"legacy","meaning":"遺產","example":"The restored library was the teacher's lasting legacy.","example_zh":"修復圖書館是老師留下的長久遺產。","original_meaning":"遺產","original_example":"Leave a legacy.","original_example_zh":"留下遺產。"},{"source_id":4733,"word":"lenient","meaning":"寬厚的","example":"The lenient coach gave the late student another chance.","example_zh":"寬厚教練再給遲到學生一次機會。","original_meaning":"寬厚的","original_example":"A lenient sentence.","original_example_zh":"一個寬大的判決。"},{"source_id":4734,"word":"liberate","meaning":"解放","example":"The historical movement sought to liberate people from forced labor.","example_zh":"那場歷史運動致力使人們擺脫強迫勞動。","original_meaning":"解放","original_example":"Liberate the city.","original_example_zh":"解放這座城市。"},{"source_id":4735,"word":"linger","meaning":"逗留","example":"We chose to linger in the peaceful garden after the tour.","example_zh":"導覽結束後，我們選擇在寧靜花園逗留。","original_meaning":"逗留","original_example":"The smell lingered.","original_example_zh":"氣味縈繞不散。"},{"source_id":4736,"word":"lucid","meaning":"清楚的","example":"Her lucid explanation made the difficult mechanism easy to understand.","example_zh":"她清楚說明，讓難懂機構變得易懂。","original_meaning":"清楚的","original_example":"A lucid explanation.","original_example_zh":"淺顯易懂的解釋。"},{"source_id":4737,"word":"ludicrous","meaning":"荒謬的","example":"The tiny paper boat made the plan to carry a person seem ludicrous.","example_zh":"小紙船讓載人的計畫顯得荒謬。","original_meaning":"荒謬的","original_example":"A ludicrous idea.","original_example_zh":"一個荒謬的主意。"},{"source_id":4738,"word":"magnify","meaning":"放大","example":"The lens could magnify the tiny pattern on the leaf.","example_zh":"鏡片能放大葉子上的微小紋理。","original_meaning":"放大","original_example":"Magnify the image.","original_example_zh":"放大影像。"},{"source_id":4739,"word":"malicious","meaning":"惡意的","example":"The novel showed how a malicious rumor damaged a friendship.","example_zh":"小說呈現惡意謠言如何損害友誼。","original_meaning":"惡意的","original_example":"A malicious attack.","original_example_zh":"惡意攻擊。"},{"source_id":4740,"word":"manipulate","meaning":"操縱；操作","example":"The students learned to manipulate the robot's arm with a controller.","example_zh":"學生學會用控制器操作機器手臂。","original_meaning":"操縱","original_example":"Manipulate data.","original_example_zh":"處理數據。"},{"source_id":4741,"word":"meager","meaning":"微薄的","example":"The meager harvest left the farming family with little to sell.","example_zh":"微薄收成讓農家可賣的作物很少。","original_meaning":"微薄的","original_example":"A meager salary.","original_example_zh":"微薄的薪水。"},{"source_id":4742,"word":"negate","meaning":"否定；抵銷","example":"One loose joint could negate the benefit of the stronger beams.","example_zh":"一個鬆動接合處可能抵銷較強梁柱的好處。","original_meaning":"否定","original_example":"Negate the effect.","original_example_zh":"抵消影響。"},{"source_id":4743,"word":"negligible","meaning":"可忽略的","example":"The tiny scratch had a negligible effect on the model's strength.","example_zh":"小刮痕對模型強度的影響可忽略。","original_meaning":"可忽略的","original_example":"A negligible amount.","original_example_zh":"微不足道的數量。"},{"source_id":4744,"word":"oblivious","meaning":"渾然不知的","example":"Engrossed in her book, she was oblivious to the light rain outside.","example_zh":"她專心讀書，渾然不知外面飄起小雨。","original_meaning":"渾然不知的","original_example":"Oblivious to danger.","original_example_zh":"對危險渾然不覺。"},{"source_id":4745,"word":"obstinate","meaning":"固執的","example":"The obstinate character refused to consider a safer design.","example_zh":"固執角色拒絕考慮較安全設計。","original_meaning":"固執的","original_example":"An obstinate refusal.","original_example_zh":"頑固的拒絕。"},{"source_id":4746,"word":"obnoxious","meaning":"令人討厭的","example":"The obnoxious noise made it difficult to study.","example_zh":"令人討厭的噪音使人難以讀書。","original_meaning":"令人討厭的","original_example":"Obnoxious behavior.","original_example_zh":"令人厭惡的行為。"},{"source_id":4747,"word":"ominous","meaning":"不祥的","example":"The ominous clouds prompted the guide to end the walk early.","example_zh":"不祥烏雲促使嚮導提早結束散步。","original_meaning":"不祥的","original_example":"An ominous sign.","original_example_zh":"不祥的徵兆。"},{"source_id":4748,"word":"ornate","meaning":"華麗的","example":"The ornate frame surrounded a simple landscape painting.","example_zh":"華麗畫框包圍一幅簡單風景畫。","original_meaning":"華麗的","original_example":"An ornate design.","original_example_zh":"華麗的設計。"},{"source_id":4749,"word":"ostentatious","meaning":"炫耀的","example":"The ostentatious entrance seemed excessive for such a small building.","example_zh":"對這麼小的建築而言，炫耀式入口顯得過分。","original_meaning":"炫耀的","original_example":"An ostentatious display.","original_example_zh":"浮誇的展示。"},{"source_id":4750,"word":"overt","meaning":"公開的","example":"The students offered overt support by volunteering for the project.","example_zh":"學生自願加入專案，公開表達支持。","original_meaning":"公開的","original_example":"An overt threat.","original_example_zh":"公開的威脅。"},{"source_id":4751,"word":"pacify","meaning":"安撫","example":"The librarian tried to pacify the upset visitor with a clear explanation.","example_zh":"圖書館員試著清楚說明，安撫不悅訪客。","original_meaning":"安撫","original_example":"Pacify the crowd.","original_example_zh":"安撫群眾。"},{"source_id":4752,"word":"palatable","meaning":"可口的","example":"The fresh herbs made the simple soup more palatable.","example_zh":"新鮮香草讓簡單湯品更可口。","original_meaning":"可口的","original_example":"A palatable solution.","original_example_zh":"一個可接受的解決方案。"},{"source_id":4753,"word":"parcel","meaning":"包裹","example":"The parcel contained new books for the school library.","example_zh":"包裹內裝著學校圖書館的新書。","original_meaning":"包裹","original_example":"Receive a parcel.","original_example_zh":"收到包裹。"},{"source_id":4754,"word":"parity","meaning":"平等","example":"The plan aimed at parity between the two clubs in access to the hall.","example_zh":"計畫希望兩個社團平等使用禮堂。","original_meaning":"平等","original_example":"Gender parity.","original_example_zh":"性別平等。"},{"source_id":4755,"word":"pastoral","meaning":"田園的","example":"The pastoral scene showed sheep beside a quiet stream.","example_zh":"田園景象呈現安靜溪流旁的羊群。","original_meaning":"田園的","original_example":"A pastoral landscape.","original_example_zh":"田園風光。"},{"source_id":4756,"word":"patronize","meaning":"光顧","example":"The students chose to patronize the small bookshop near school.","example_zh":"學生選擇光顧學校附近的小書店。","original_meaning":"光顧","original_example":"Patronize the shop.","original_example_zh":"光顧這家店。"},{"source_id":4757,"word":"penal","meaning":"刑罰的","example":"The museum examined changes in the penal system over time.","example_zh":"博物館探討刑罰制度隨時間的變化。","original_meaning":"刑罰的","original_example":"The penal system.","original_example_zh":"刑罰制度。"},{"source_id":4758,"word":"perilous","meaning":"危險的","example":"The model showed why the narrow cliff path was perilous.","example_zh":"模型展示狹窄崖邊步道為何危險。","original_meaning":"危險的","original_example":"A perilous journey.","original_example_zh":"一段險象環生的旅程。"},{"source_id":4759,"word":"peripheral","meaning":"邊緣的","example":"The small garden occupied a peripheral area of the campus.","example_zh":"小花園位於校園邊緣區域。","original_meaning":"邊緣的","original_example":"A peripheral issue.","original_example_zh":"一個次要問題。"},{"source_id":4760,"word":"perplexing","meaning":"令人困惑的","example":"The model's uneven movement posed a perplexing problem.","example_zh":"模型動作不均勻，形成令人困惑的問題。","original_meaning":"令人困惑的","original_example":"A perplexing problem.","original_example_zh":"一個令人困惑的問題。"},{"source_id":4761,"word":"persevere","meaning":"堅持不懈","example":"The team decided to persevere after the first model failed.","example_zh":"第一個模型失敗後，團隊決定堅持下去。","original_meaning":"堅持不懈","original_example":"Persevere through hardship.","original_example_zh":"在艱難中堅持不懈。"},{"source_id":4762,"word":"pertinent","meaning":"相關的","example":"Her question was pertinent to the safety of the new path.","example_zh":"她的問題與新步道安全密切相關。","original_meaning":"相關的","original_example":"A pertinent question.","original_example_zh":"一個切題的問題。"},{"source_id":4763,"word":"pervasive","meaning":"普遍的","example":"The pervasive scent of pine filled the forest path.","example_zh":"松木氣味遍布整條森林步道。","original_meaning":"普遍的","original_example":"A pervasive influence.","original_example_zh":"一種無所不在的影響。"},{"source_id":4764,"word":"pessimistic","meaning":"悲觀的","example":"The pessimistic student expected the model to fail before the test began.","example_zh":"悲觀學生在測試前就認為模型會失敗。","original_meaning":"悲觀的","original_example":"A pessimistic view.","original_example_zh":"一種悲觀的觀點。"},{"source_id":4765,"word":"placid","meaning":"平靜的","example":"The placid lake reflected the clouds perfectly.","example_zh":"平靜湖面完整映出白雲。","original_meaning":"平靜的","original_example":"A placid lake.","original_example_zh":"一片寧靜的湖泊。"},{"source_id":4766,"word":"plight","meaning":"困境","example":"The volunteers responded to the plight of families displaced by the flood.","example_zh":"志工回應洪水後失去住所家庭的困境。","original_meaning":"困境","original_example":"The plight of refugees.","original_example_zh":"難民的困境。"},{"source_id":4767,"word":"plummet","meaning":"暴跌；驟降","example":"The temperature began to plummet after sunset.","example_zh":"日落後氣溫開始驟降。","original_meaning":"暴跌","original_example":"Stocks plummeted.","original_example_zh":"股票暴跌。"},{"source_id":4768,"word":"poignant","meaning":"感人的","example":"The old photographs formed a poignant reminder of the teacher's kindness.","example_zh":"老照片感人地提醒大家老師的善良。","original_meaning":"感人的","original_example":"A poignant story.","original_example_zh":"一個感人至深的故事。"},{"source_id":4769,"word":"potent","meaning":"強效的；濃烈的","example":"A tiny amount of the potent pigment changed the whole mixture's color.","example_zh":"一點濃烈顏料就改變整碗混合物的顏色。","original_meaning":"強效的","original_example":"A potent drug.","original_example_zh":"一種強效藥物。"},{"source_id":4770,"word":"precarious","meaning":"不穩定的","example":"The tall tower stood in a precarious balance on its narrow base.","example_zh":"高塔在狹窄底座上處於不穩平衡。","original_meaning":"不穩定的","original_example":"A precarious situation.","original_example_zh":"岌岌可危的局面。"},{"source_id":4771,"word":"precedent","meaning":"先例","example":"The successful shared rehearsal set a precedent for future cooperation.","example_zh":"成功共同排練為未來合作建立先例。","original_meaning":"先例","original_example":"Set a precedent.","original_example_zh":"樹立先例。"},{"source_id":4772,"word":"preclude","meaning":"排除","example":"The narrow entrance would preclude moving the large model into the room.","example_zh":"狹窄入口使大型模型無法搬進房間。","original_meaning":"排除","original_example":"Preclude the possibility.","original_example_zh":"排除這種可能性。"},{"source_id":4773,"word":"preeminent","meaning":"卓越的","example":"The preeminent historian visited the school to discuss the old harbor.","example_zh":"卓越歷史學家到學校談論老港口。","original_meaning":"卓越的","original_example":"A preeminent expert.","original_example_zh":"一位傑出的專家。"},{"source_id":4774,"word":"prohibit","meaning":"禁止","example":"The reserve's rules prohibit visitors from approaching the nests.","example_zh":"保護區規定禁止訪客靠近鳥巢。","original_meaning":"禁止","original_example":"Prohibited by law.","original_example_zh":"法律禁止。"},{"source_id":4775,"word":"prolific","meaning":"多產的","example":"The prolific composer wrote music for many school concerts.","example_zh":"多產作曲家為多場校園音樂會譜曲。","original_meaning":"多產的","original_example":"A prolific writer.","original_example_zh":"多產的作家。"},{"source_id":4776,"word":"propensity","meaning":"傾向","example":"Her propensity to ask questions made every visit a learning opportunity.","example_zh":"她愛提問的傾向，使每次參訪都成為學習機會。","original_meaning":"傾向","original_example":"A propensity for risk.","original_example_zh":"冒險傾向。"},{"source_id":4777,"word":"purport","meaning":"聲稱","example":"The old letter purported to reveal the treasure's location.","example_zh":"那封老信聲稱揭露寶藏位置。","original_meaning":"聲稱","original_example":"Purport to be true.","original_example_zh":"聲稱屬實。"},{"source_id":4778,"word":"qualm","meaning":"疑慮","example":"She had a qualm about using the fragile cup in the experiment.","example_zh":"她對在實驗中使用脆弱杯子感到疑慮。","original_meaning":"疑慮","original_example":"Have no qualms.","original_example_zh":"毫無顧慮。"},{"source_id":4779,"word":"quandary","meaning":"困境","example":"The team was in a quandary about which design to submit.","example_zh":"團隊陷入該提交哪個設計的兩難。","original_meaning":"困境","original_example":"In a quandary.","original_example_zh":"進退維谷。"},{"source_id":4780,"word":"quash","meaning":"撤銷","example":"The appeal court decided to quash the earlier ruling.","example_zh":"上訴法院決定撤銷先前裁決。","original_meaning":"撤銷","original_example":"Quash the verdict.","original_example_zh":"推翻判決。"},{"source_id":4781,"word":"quell","meaning":"鎮壓；平息","example":"The clear explanation helped quell the students' fears.","example_zh":"清楚說明幫助平息學生恐懼。","original_meaning":"鎮壓","original_example":"Quell the uprising.","original_example_zh":"鎮壓起義。"},{"source_id":4782,"word":"query","meaning":"詢問","example":"The librarian answered a query about the town's oldest map.","example_zh":"館員回答關於城鎮最古老地圖的詢問。","original_meaning":"詢問","original_example":"Submit a query.","original_example_zh":"提交查詢。"},{"source_id":4783,"word":"ramification","meaning":"後果","example":"Closing the bridge had an unexpected ramification for the market.","example_zh":"封橋對市集造成意料之外的後果。","original_meaning":"後果","original_example":"Serious ramifications.","original_example_zh":"嚴重的後果。"},{"source_id":4784,"word":"rebuke","meaning":"斥責","example":"The coach chose to rebuke the unfair behavior calmly.","example_zh":"教練選擇冷靜斥責不公平行為。","original_meaning":"斥責","original_example":"Rebuke sharply.","original_example_zh":"嚴厲斥責。"},{"source_id":4785,"word":"recede","meaning":"後退","example":"The floodwaters began to recede from the empty road.","example_zh":"洪水開始從空道路退去。","original_meaning":"後退","original_example":"The waters receded.","original_example_zh":"水退去了。"},{"source_id":4786,"word":"reckless","meaning":"魯莽的","example":"The reckless plan ignored the warning about the storm.","example_zh":"魯莽計畫忽略暴風雨警告。","original_meaning":"魯莽的","original_example":"Reckless driving.","original_example_zh":"魯莽駕駛。"},{"source_id":4787,"word":"refute","meaning":"駁斥","example":"The measurements helped refute the claim that both beams were equal.","example_zh":"測量幫助駁斥兩根梁同長的說法。","original_meaning":"駁斥","original_example":"Refute the claim.","original_example_zh":"駁斥該主張。"},{"source_id":4788,"word":"reluctant","meaning":"不情願的","example":"The reluctant speaker gained confidence after a short practice.","example_zh":"不情願講者在短暫練習後增添信心。","original_meaning":"不情願的","original_example":"A reluctant participant.","original_example_zh":"一位不情願的參與者。"},{"source_id":4789,"word":"reminiscent","meaning":"令人回想的","example":"The new garden was reminiscent of the one behind her childhood home.","example_zh":"新花園讓她想起童年家後那座。","original_meaning":"令人回想的","original_example":"Reminiscent of childhood.","original_example_zh":"令人回想起童年。"},{"source_id":4790,"word":"renovate","meaning":"翻新","example":"The volunteers will renovate the library's old reading room.","example_zh":"志工將翻新圖書館老閱覽室。","original_meaning":"翻新","original_example":"Renovate the house.","original_example_zh":"翻新房子。"},{"source_id":4791,"word":"repeal","meaning":"撤銷","example":"The council voted to repeal the outdated park restriction.","example_zh":"議會投票廢除過時公園限制。","original_meaning":"撤銷","original_example":"Repeal the ban.","original_example_zh":"廢除禁令。"},{"source_id":4792,"word":"replenish","meaning":"補充","example":"The staff will replenish the shelves with donated books.","example_zh":"工作人員將用捐贈書籍補滿書架。","original_meaning":"補充","original_example":"Replenish supplies.","original_example_zh":"補充物資。"},{"source_id":4793,"word":"reprimand","meaning":"訓斥","example":"The teacher chose to reprimand the student calmly for repeated interruptions.","example_zh":"老師選擇冷靜訓斥反覆打斷發言的學生。","original_meaning":"訓斥","original_example":"Officially reprimanded.","original_example_zh":"受到正式譴責。"},{"source_id":4794,"word":"repudiate","meaning":"否認","example":"The curator publicly repudiated the false claim about the painting.","example_zh":"策展人公開否認關於畫作的不實說法。","original_meaning":"否認","original_example":"Repudiate the accusation.","original_example_zh":"駁斥指控。"},{"source_id":4795,"word":"resemble","meaning":"相似","example":"The insect's body could resemble a dry leaf.","example_zh":"昆蟲身體能像一片乾葉。","original_meaning":"相似","original_example":"Closely resemble each other.","original_example_zh":"彼此極為相似。"},{"source_id":4796,"word":"revelry","meaning":"狂歡","example":"The joyful revelry continued after the school concert.","example_zh":"校園音樂會後，歡樂慶祝持續進行。","original_meaning":"狂歡","original_example":"Night of revelry.","original_example_zh":"狂歡之夜。"},{"source_id":4797,"word":"revert","meaning":"恢復","example":"The team decided to revert to the simpler design.","example_zh":"團隊決定恢復採用較簡單設計。","original_meaning":"恢復","original_example":"Revert to old ways.","original_example_zh":"恢復舊制。"},{"source_id":4798,"word":"revoke","meaning":"撤銷","example":"The council agreed to revoke the unsafe event's permit.","example_zh":"議會同意撤銷不安全活動的許可。","original_meaning":"撤銷","original_example":"Revoke the permit.","original_example_zh":"撤銷許可證。"},{"source_id":4799,"word":"rigorous","meaning":"嚴格的","example":"The engineers applied rigorous checks to every part of the bridge.","example_zh":"工程師對橋梁各部分進行嚴格檢查。","original_meaning":"嚴格的","original_example":"Rigorous testing.","original_example_zh":"嚴格的測試。"},{"source_id":4800,"word":"ruthless","meaning":"無情的","example":"The story's ruthless ruler cared more for power than for the villagers.","example_zh":"故事中無情統治者重權力、輕村民需要。","original_meaning":"無情的","original_example":"A ruthless dictator.","original_example_zh":"無情的獨裁者。"},{"source_id":4801,"word":"saturate","meaning":"使飽和","example":"Water began to saturate the sponge.","example_zh":"水開始浸透海綿。","original_meaning":"使飽和","original_example":"Saturate the market.","original_example_zh":"飽和市場。"},{"source_id":4802,"word":"serene","meaning":"寧靜的","example":"The serene courtyard offered a quiet place to read.","example_zh":"寧靜庭院提供安靜閱讀場所。","original_meaning":"寧靜的","original_example":"A serene environment.","original_example_zh":"寧靜的環境。"},{"source_id":4803,"word":"solicit","meaning":"徵求","example":"The museum will solicit suggestions from local students.","example_zh":"博物館將徵求當地學生建議。","original_meaning":"徵求","original_example":"Solicit donations.","original_example_zh":"募款。"},{"source_id":4804,"word":"solemn","meaning":"莊嚴的","example":"The visitors stood in solemn silence at the memorial.","example_zh":"訪客在紀念碑前莊嚴默立。","original_meaning":"莊嚴的","original_example":"A solemn occasion.","original_example_zh":"莊嚴的場合。"},{"source_id":4805,"word":"stifle","meaning":"壓制","example":"The rigid rules could stifle the students' creativity.","example_zh":"僵化規則可能壓制學生創意。","original_meaning":"壓制","original_example":"Stifle creativity.","original_example_zh":"扼殺創意。"},{"source_id":4806,"word":"subtle","meaning":"微妙的","example":"A subtle change in color made the portrait warmer.","example_zh":"色彩細微變化讓肖像更溫暖。","original_meaning":"微妙的","original_example":"A subtle difference.","original_example_zh":"一絲微妙的差異。"},{"source_id":4807,"word":"succumb","meaning":"屈服；抵擋不住","example":"The old fence finally succumbed to years of rain.","example_zh":"老柵欄終究抵擋不住多年雨淋。","original_meaning":"屈服","original_example":"Succumb to pressure.","original_example_zh":"屈服於壓力。"},{"source_id":4808,"word":"superfluous","meaning":"多餘的","example":"The extra decoration was superfluous on the simple wooden box.","example_zh":"簡單木盒上的額外裝飾顯得多餘。","original_meaning":"多餘的","original_example":"Superfluous details.","original_example_zh":"多餘的細節。"},{"source_id":4809,"word":"supplant","meaning":"取代","example":"The new digital catalog began to supplant the old card system.","example_zh":"新數位目錄開始取代舊卡片系統。","original_meaning":"取代","original_example":"Supplant the old system.","original_example_zh":"取代舊系統。"},{"source_id":4810,"word":"surmount","meaning":"克服","example":"The team found a way to surmount the shortage of materials.","example_zh":"團隊找到克服材料短缺的方法。","original_meaning":"克服","original_example":"Surmount challenges.","original_example_zh":"克服挑戰。"},{"source_id":4811,"word":"sustain","meaning":"維持","example":"Regular care helped sustain the garden through the dry season.","example_zh":"定期照料幫助花園度過乾季、維持生長。","original_meaning":"維持","original_example":"Sustain growth.","original_example_zh":"維持增長。"},{"source_id":4812,"word":"swindle","meaning":"詐騙","example":"The detective stopped a dealer's attempt to swindle the collector.","example_zh":"偵探阻止商人企圖詐騙收藏家。","original_meaning":"詐騙","original_example":"Swindled out of money.","original_example_zh":"被騙走錢財。"},{"source_id":4813,"word":"tacit","meaning":"心照不宣的","example":"A quiet nod showed their tacit agreement.","example_zh":"輕輕點頭顯示彼此心照不宣的同意。","original_meaning":"心照不宣的","original_example":"Tacit agreement.","original_example_zh":"默契。"},{"source_id":4814,"word":"tenacious","meaning":"頑強的","example":"The tenacious student kept refining the design after each test.","example_zh":"頑強學生在每次測試後持續改良設計。","original_meaning":"頑強的","original_example":"A tenacious fighter.","original_example_zh":"一位頑強的鬥士。"},{"source_id":4815,"word":"thwart","meaning":"挫敗","example":"The sturdy fence helped thwart deer entering the garden.","example_zh":"堅固柵欄阻止鹿進入花園。","original_meaning":"挫敗","original_example":"Thwart the plan.","original_example_zh":"挫敗該計畫。"},{"source_id":4816,"word":"transcend","meaning":"超越","example":"Their friendship could transcend differences in language.","example_zh":"他們的友誼能超越語言差異。","original_meaning":"超越","original_example":"Transcend boundaries.","original_example_zh":"超越界限。"},{"source_id":4817,"word":"transient","meaning":"短暫的","example":"The transient glow of sunset faded behind the hills.","example_zh":"短暫夕陽光芒在山後漸漸消退。","original_meaning":"短暫的","original_example":"A transient phase.","original_example_zh":"一個過渡階段。"},{"source_id":4818,"word":"tremor","meaning":"震動","example":"The seismograph recorded a slight tremor.","example_zh":"地震儀記錄一次輕微震動。","original_meaning":"震動","original_example":"An earthquake tremor.","original_example_zh":"地震餘震。"},{"source_id":4819,"word":"ubiquitous","meaning":"無處不在的","example":"Bicycles were ubiquitous around the university campus.","example_zh":"大學校園到處都是自行車。","original_meaning":"無處不在的","original_example":"Ubiquitous smartphones.","original_example_zh":"無所不在的智慧型手機。"},{"source_id":4820,"word":"unambiguous","meaning":"明確的","example":"The unambiguous arrow showed the only safe route.","example_zh":"明確箭頭指出唯一安全路線。","original_meaning":"明確的","original_example":"An unambiguous statement.","original_example_zh":"明確無誤的聲明。"},{"source_id":4821,"word":"usurp","meaning":"篡奪","example":"The novel's minister tried to usurp the ruler's authority.","example_zh":"小說中大臣企圖篡奪統治者權威。","original_meaning":"篡奪","original_example":"Usurp the throne.","original_example_zh":"篡奪王位。"},{"source_id":4822,"word":"utilitarian","meaning":"實用主義的；重實用的","example":"The utilitarian desk favored practical storage over decoration.","example_zh":"實用書桌重視收納功能，勝過裝飾。","original_meaning":"實用主義的","original_example":"A utilitarian design.","original_example_zh":"實用主義的設計。"},{"source_id":4823,"word":"vain","meaning":"徒勞的","example":"Their vain search ended without finding the missing piece.","example_zh":"他們徒勞搜尋，最後仍沒找到遺失零件。","original_meaning":"徒勞的","original_example":"A vain attempt.","original_example_zh":"徒勞的嘗試。"},{"source_id":4824,"word":"vanquish","meaning":"征服；擊敗","example":"The chess team hoped to vanquish its strongest rival.","example_zh":"棋隊希望擊敗最強對手。","original_meaning":"征服","original_example":"Vanquish the enemy.","original_example_zh":"擊敗敵人。"},{"source_id":4825,"word":"venerate","meaning":"尊崇","example":"The community continued to venerate the teacher who founded the library.","example_zh":"社區持續尊崇創建圖書館的老師。","original_meaning":"尊崇","original_example":"Venerate ancestors.","original_example_zh":"祭拜祖先。"},{"source_id":4826,"word":"verbose","meaning":"冗長的","example":"The verbose explanation became clearer after unnecessary details were removed.","example_zh":"刪去不必要細節後，冗長說明變清楚。","original_meaning":"冗長的","original_example":"A verbose report.","original_example_zh":"一份詳盡的報告。"},{"source_id":4827,"word":"vigilant","meaning":"警覺的","example":"The vigilant guide noticed the loose stone before anyone stepped on it.","example_zh":"警覺嚮導在有人踩上去前發現鬆石。","original_meaning":"警覺的","original_example":"Remain vigilant.","original_example_zh":"保持警惕。"},{"source_id":4828,"word":"vindicate","meaning":"證明清白","example":"The clear photograph helped vindicate the wrongly accused student.","example_zh":"清楚照片幫助證明遭誤控學生清白。","original_meaning":"證明清白","original_example":"Vindicated by evidence.","original_example_zh":"被證據證明是清白的。"},{"source_id":4829,"word":"voracious","meaning":"貪婪的；求知若渴的","example":"The voracious reader borrowed another stack of books.","example_zh":"求知若渴讀者又借一疊書。","original_meaning":"貪婪的","original_example":"A voracious reader.","original_example_zh":"一位如飢似渴的讀者。"},{"source_id":4830,"word":"wane","meaning":"減弱","example":"The wind began to wane as evening approached.","example_zh":"傍晚將至，風開始減弱。","original_meaning":"減弱","original_example":"Interest waned.","original_example_zh":"興趣減退。"}]$senior_content$::jsonb; begin
perform 1 from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' for update of w;
if (select count(*) from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' and ((w.meaning,w.example,w.example_zh) is not distinct from (c.original_meaning,c.original_example,c.original_example_zh) or (w.meaning,w.example,w.example_zh) is not distinct from (c.meaning,c.example,c.example_zh))) <> 100 then raise exception 'Senior source rows changed; refusing overwrite'; end if;
update public.word_bank w set meaning=c.meaning,example=c.example,example_zh=c.example_zh from jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) where w.id=c.source_id and w.level='senior' and w.word=c.word;
end $guard$;
insert into public.word_illustrations(id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version) select id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version from jsonb_to_recordset($senior_rows$[{"id":"senior-lavish-01-v1","level":"senior","word":"lavish","sort_order":1,"sense":"奢華的","alt_zh":"虛構成年主人看著華麗大廳的過量宴席，旁人思考減少浪費。","example":"The lavish banquet used far more food than the guests could eat.","example_zh":"奢華宴席準備遠超賓客能吃完的食物。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/lavish-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-legacy-01-v1","level":"senior","word":"legacy","sort_order":1,"sense":"遺產","alt_zh":"高中生與成年校友在修復後圖書館欣賞退休教師肖像。","example":"The restored library was the teacher's lasting legacy.","example_zh":"修復圖書館是老師留下的長久遺產。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/legacy-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-lenient-01-v1","level":"senior","word":"lenient","sort_order":1,"sense":"寬厚的","alt_zh":"成年教練溫和邀遲到高中生加入棋隊練習。","example":"The lenient coach gave the late student another chance.","example_zh":"寬厚教練再給遲到學生一次機會。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/lenient-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-liberate-01-v1","level":"senior","word":"liberate","sort_order":1,"sense":"解放","alt_zh":"高中生參觀歷史館的自由題材畫作，成年人物走出敞開城門，無束縛傷害。","example":"The historical movement sought to liberate people from forced labor.","example_zh":"那場歷史運動致力使人們擺脫強迫勞動。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/liberate-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-linger-01-v1","level":"senior","word":"linger","sort_order":1,"sense":"逗留","alt_zh":"高中團與成年老師在花園長椅悠閒欣賞花木。","example":"We chose to linger in the peaceful garden after the tour.","example_zh":"導覽結束後，我們選擇在寧靜花園逗留。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/linger-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-lucid-01-v1","level":"senior","word":"lucid","sort_order":1,"sense":"清楚的","alt_zh":"高中女生向同學與成年老師清楚解說透明齒輪教具。","example":"Her lucid explanation made the difficult mechanism easy to understand.","example_zh":"她清楚說明，讓難懂機構變得易懂。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/lucid-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-ludicrous-01-v1","level":"senior","word":"ludicrous","sort_order":1,"sense":"荒謬的","alt_zh":"高中生與成年老師比較水盆中小紙船及人物小模型，露出懷疑笑容。","example":"The tiny paper boat made the plan to carry a person seem ludicrous.","example_zh":"小紙船讓載人的計畫顯得荒謬。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/ludicrous-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-magnify-01-v1","level":"senior","word":"magnify","sort_order":1,"sense":"放大","alt_zh":"高中生在成年老師旁透過放大鏡觀察綠葉脈紋。","example":"The lens could magnify the tiny pattern on the leaf.","example_zh":"鏡片能放大葉子上的微小紋理。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/magnify-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-malicious-01-v1","level":"senior","word":"malicious","sort_order":1,"sense":"惡意的","alt_zh":"高中文學課討論插畫中因不實消息疏遠的兩位成年角色，無文字。","example":"The novel showed how a malicious rumor damaged a friendship.","example_zh":"小說呈現惡意謠言如何損害友誼。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/malicious-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-manipulate-01-v1","level":"senior","word":"manipulate","sort_order":1,"sense":"操縱；操作","alt_zh":"成年老師監督高中生操作安全低速桌上小機器手臂。","example":"The students learned to manipulate the robot's arm with a controller.","example_zh":"學生學會用控制器操作機器手臂。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/manipulate-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-meager-01-v1","level":"senior","word":"meager","sort_order":1,"sense":"微薄的","alt_zh":"成年農人在乾旱農田旁查看少量收成，社區志工尊重地提供協助。","example":"The meager harvest left the farming family with little to sell.","example_zh":"微薄收成讓農家可賣的作物很少。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/meager-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-negate-01-v1","level":"senior","word":"negate","sort_order":1,"sense":"否定；抵銷","alt_zh":"成年老師向高中生指出厚梁模型橋上鬆動的關鍵接點。","example":"One loose joint could negate the benefit of the stronger beams.","example_zh":"一個鬆動接合處可能抵銷較強梁柱的好處。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/negate-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-negligible-01-v1","level":"senior","word":"negligible","sort_order":1,"sense":"可忽略的","alt_zh":"高中生與成年老師觀察穩固木模型上極小刮痕。","example":"The tiny scratch had a negligible effect on the model's strength.","example_zh":"小刮痕對模型強度的影響可忽略。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/negligible-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-oblivious-01-v1","level":"senior","word":"oblivious","sort_order":1,"sense":"渾然不知的","alt_zh":"高中女生在乾燥舒適圖書館專注閱讀，窗外飄小雨。","example":"Engrossed in her book, she was oblivious to the light rain outside.","example_zh":"她專心讀書，渾然不知外面飄起小雨。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/oblivious-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-obstinate-01-v1","level":"senior","word":"obstinate","sort_order":1,"sense":"固執的","alt_zh":"高中舞臺劇中虛構成年設計者抱臂堅持不穩小模型。","example":"The obstinate character refused to consider a safer design.","example_zh":"固執角色拒絕考慮較安全設計。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/obstinate-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-obnoxious-01-v1","level":"senior","word":"obnoxious","sort_order":1,"sense":"令人討厭的","alt_zh":"高中生在閱覽室因外面喧鬧而皺眉，成年館員準備協調。","example":"The obnoxious noise made it difficult to study.","example_zh":"令人討厭的噪音使人難以讀書。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/obnoxious-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-ominous-01-v1","level":"senior","word":"ominous","sort_order":1,"sense":"不祥的","alt_zh":"成年嚮導帶高中生從安全步道走向遊客中心，遠方濃雲漸深。","example":"The ominous clouds prompted the guide to end the walk early.","example_zh":"不祥烏雲促使嚮導提早結束散步。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/ominous-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-ornate-01-v1","level":"senior","word":"ornate","sort_order":1,"sense":"華麗的","alt_zh":"高中訪客在美術館欣賞葉紋精雕金框與平靜風景畫。","example":"The ornate frame surrounded a simple landscape painting.","example_zh":"華麗畫框包圍一幅簡單風景畫。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/ornate-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-ostentatious-01-v1","level":"senior","word":"ostentatious","sort_order":1,"sense":"炫耀的","alt_zh":"成年建築師與高中生比較小建築和過度華麗巨大門柱的模型。","example":"The ostentatious entrance seemed excessive for such a small building.","example_zh":"對這麼小的建築而言，炫耀式入口顯得過分。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/ostentatious-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-overt-01-v1","level":"senior","word":"overt","sort_order":1,"sense":"公開的","alt_zh":"高中生在成年老師旁踴躍舉手參加花園修復。","example":"The students offered overt support by volunteering for the project.","example_zh":"學生自願加入專案，公開表達支持。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/overt-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-pacify-01-v1","level":"senior","word":"pacify","sort_order":1,"sense":"安撫","alt_zh":"成年館員耐心向皺眉成年訪客說明安排，對方漸漸放鬆。","example":"The librarian tried to pacify the upset visitor with a clear explanation.","example_zh":"圖書館員試著清楚說明，安撫不悅訪客。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/pacify-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-palatable-01-v1","level":"senior","word":"palatable","sort_order":1,"sense":"可口的","alt_zh":"成年烹飪老師向高中生展示加入香草的熱湯。","example":"The fresh herbs made the simple soup more palatable.","example_zh":"新鮮香草讓簡單湯品更可口。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/palatable-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-parcel-01-v1","level":"senior","word":"parcel","sort_order":1,"sense":"包裹","alt_zh":"高中志工與成年館員打開裝滿新書的安全紙箱。","example":"The parcel contained new books for the school library.","example_zh":"包裹內裝著學校圖書館的新書。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/parcel-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-parity-01-v1","level":"senior","word":"parity","sort_order":1,"sense":"平等","alt_zh":"兩組高中社團與成年老師在禮堂模型前分到相同數量時段圖卡。","example":"The plan aimed at parity between the two clubs in access to the hall.","example_zh":"計畫希望兩個社團平等使用禮堂。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/parity-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-pastoral-01-v1","level":"senior","word":"pastoral","sort_order":1,"sense":"田園的","alt_zh":"高中團與成年嚮導從安全小徑欣賞綠草羊群清溪。","example":"The pastoral scene showed sheep beside a quiet stream.","example_zh":"田園景象呈現安靜溪流旁的羊群。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/pastoral-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-patronize-01-v1","level":"senior","word":"patronize","sort_order":1,"sense":"光顧","alt_zh":"高中生在社區小書店向成年店主選購書籍，無品牌文字。","example":"The students chose to patronize the small bookshop near school.","example_zh":"學生選擇光顧學校附近的小書店。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/patronize-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-penal-01-v1","level":"senior","word":"penal","sort_order":1,"sense":"刑罰的","alt_zh":"高中生與成年導覽員觀看司法史館的法院模型，無刑罰操作。","example":"The museum examined changes in the penal system over time.","example_zh":"博物館探討刑罰制度隨時間的變化。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/penal-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-perilous-01-v1","level":"senior","word":"perilous","sort_order":1,"sense":"危險的","alt_zh":"教室桌上的塑膠地形模型呈現狹窄崖邊小徑，入口有封閉柵欄，畫面只有模型。","example":"The model showed why the narrow cliff path was perilous.","example_zh":"模型展示狹窄崖邊步道為何危險。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/perilous-01-v1.webp","local_path":"","style":"generat